NETS_SEMARANG = [ipaddress.ip_network(n) for n in CIDRS_SEMARANG]
NETS_JATENG = [ipaddress.ip_network(n) for n in CIDRS_JATENG]
NETS_MAJOR = [ipaddress.ip_network(n) for n in CIDRS_MAJOR]

def generate_tujuhcahaya_geo_ip():
    """
    Distribusi Khusus Tujuhcahaya Radio:
    - ~40% Jawa Tengah (Jitter 37% - 43%)
    - ~30% Semarang (Jitter 27% - 33%)
    - ~30% Kota Besar Indonesia (Sisa %)
    """
    w_jateng = random.uniform(37.0, 43.0)
    w_semarang = random.uniform(27.0, 33.0)
    w_major = 100.0 - w_jateng - w_semarang

    region = random.choices(
        ['jateng', 'semarang', 'major'],
        weights=[w_jateng, w_semarang, w_major],
        k=1
    )[0]

    if region == 'jateng':
        net = random.choice(NETS_JATENG)
    elif region == 'semarang':
        net = random.choice(NETS_SEMARANG)
    else:
        net = random.choice(NETS_MAJOR)

    if net.num_addresses == 1:
        return str(net.network_address), region
    if net.num_addresses > 2:
        offset = random.randint(1, net.num_addresses - 2)
    else:
        offset = 0
    return str(net.network_address + offset), region

